function validate([points]) {
  if (!Array.isArray(points) || points.length < 1 || points.length > 10000) return 'points needs 1 to 10^4 points.';
  for (const p of points) {
    if (!Array.isArray(p) || p.length !== 2) return 'Each point is a pair [x, y].';
    if (p.some(v => !Number.isInteger(v) || v < -1e8 || v > 1e8)) return 'Each coordinate is an integer between -10^8 and 10^8.';
  }
  return null;
}

