function isReflected(points) {
  let minX = Infinity;
  let maxX = -Infinity;
  const seen = new Set();
  for (const [x, y] of points) {
    minX = Math.min(minX, x);
    maxX = Math.max(maxX, x);
    seen.add(x + ',' + y);
  }

  const sum = minX + maxX;
  for (const [x, y] of points) {
    if (!seen.has((sum - x) + ',' + y)) return false;
  }
  return true;
}

