function isReflected(points) {
  const has = (x, y) => points.some(p => p[0] === x && p[1] === y);
  // The first point must land on some point q, which fixes the line at (points[0].x + q.x) / 2.
  for (const q of points) {
    const twice = points[0][0] + q[0];
    if (points.every(([x, y]) => has(twice - x, y))) return true;
  }
  return false;
}

