function generate(rand, size) {
  const large = size === 'large';
  const span = large || rand() < 0.3 ? 100000000 : 5;
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const n = large ? 2000 : pick(1, 8);
  const mode = rand();
  if (mode < 0.2) return [Array.from({ length: n }, () => [pick(-span, span), pick(-span, span)])];
  // twice is 2c for the mirror line x = c; x is chosen so that its mirror twice - x stays in range.
  const twice = pick(-span, span);
  const low = Math.max(-span, twice - span);
  const high = Math.min(span, twice + span);
  const points = [];
  while (points.length < n) {
    const roll = rand();
    const y = pick(-span, span);
    const last = points.length === n - 1;
    if ((roll < 0.15 || last) && twice % 2 === 0) points.push([twice / 2, y]);
    else if ((roll < 0.3 || last) && points.length > 0) points.push([...points[pick(0, points.length - 1)]]);
    else {
      const x = pick(low, high);
      points.push([x, y]);
      if (points.length < n) points.push([twice - x, y]);
    }
  }
  if (mode < 0.5) {
    // Nudge one point so that the mirror image usually breaks.
    const p = points[pick(0, n - 1)];
    const axis = rand() < 0.5 ? 0 : 1;
    p[axis] = p[axis] === span ? span - 1 : p[axis] + 1;
  }
  for (let i = points.length - 1; i > 0; i--) {
    const j = pick(0, i);
    [points[i], points[j]] = [points[j], points[i]];
  }
  return [points];
}
